@namespace sv_bb4112eb02274c47a87b1948b8692560.Components.Pages.Settings
@using sv_bb4112eb02274c47a87b1948b8692560.Services
@inject ISettingsService SettingsService

<div class="card mb-3">
    <div class="card-header"><h5 class="mb-0">Security Settings</h5></div>
    <div class="card-body">
        @if (_loading)
        {
            <div class="text-center p-4"><div class="spinner-border" role="status"></div></div>
        }
        else
        {
            @if (!string.IsNullOrEmpty(_message))
            {
                <div class="alert @(_messageIsError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
                    @_message
                    <button type="button" class="btn-close" @onclick="() => _message = null"></button>
                </div>
            }

            <!-- Change Password Panel -->
            <div class="mb-4">
                <button class="btn btn-outline-secondary w-100 text-start d-flex justify-content-between align-items-center"
                        @onclick="() => _passwordExpanded = !_passwordExpanded">
                    <span><i class="bi bi-key me-2"></i>Change Password</span>
                    <i class="bi @(_passwordExpanded ? "bi-chevron-up" : "bi-chevron-down")"></i>
                </button>

                @if (_passwordExpanded)
                {
                    <div class="border rounded p-3 mt-2">
                        <div class="mb-3">
                            <label class="form-label">Current Password</label>
                            <input type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">New Password</label>
                            <input type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Confirm New Password</label>
                            <input type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-warning" @onclick="ChangePasswordAsync">Update Password</button>
                    </div>
                }
            </div>

            <!-- Two-Factor Authentication -->
            <div class="mb-4 p-3 border rounded">
                <div class="d-flex justify-content-between align-items-center">
                    <div>
                        <h6 class="mb-1">Two-Factor Authentication</h6>
                        <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                            @(_twoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                    </div>
                    <div class="form-check form-switch">
                        <input type="checkbox" class="form-check-input" id="twoFactor" @bind="_twoFactorEnabled" />
                    </div>
                </div>
                @if (_lastPasswordChange.HasValue)
                {
                    <p class="text-muted small mt-2 mb-0">Last password change: @_lastPasswordChange.Value.ToString("MMM dd, yyyy")</p>
                }
            </div>

            <!-- Active Sessions -->
            <h6 class="mb-3">Active Sessions</h6>
            @if (_sessions.Count == 0)
            {
                <p class="text-muted">No active sessions.</p>
            }
            else
            {
                <div class="table-responsive">
                    <table class="table table-sm table-hover">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in _sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@session.LastActive.ToString("g")</td>
                                    <td>
                                        @if (session != _sessions.First())
                                        {
                                            @if (_confirmRevokeId == session.Id)
                                            {
                                                <span class="me-2 text-danger small">Revoke this session?</span>
                                                <button class="btn btn-sm btn-danger me-1" @onclick="() => RevokeSessionAsync(session.Id)">Yes</button>
                                                <button class="btn btn-sm btn-outline-secondary" @onclick="() => _confirmRevokeId = null">No</button>
                                            }
                                            else
                                            {
                                                <button class="btn btn-sm btn-outline-danger" @onclick="() => _confirmRevokeId = session.Id">Revoke</button>
                                            }
                                        }
                                        else
                                        {
                                            <span class="badge bg-info">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }
        }
    </div>
</div>

@code {
    private bool _loading = true;
    private bool _passwordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = new();
    private string? _confirmRevokeId;
    private string? _message;
    private bool _messageIsError;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _lastPasswordChange = settings.LastPasswordChange;
        _sessions = settings.Sessions.ToList();
        _loading = false;
    }

    private async Task ChangePasswordAsync()
    {
        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            ShowMessage("New password cannot be empty.", true);
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            ShowMessage("Passwords do not match.", true);
            return;
        }

        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
            _passwordExpanded = false;
            ShowMessage("Password updated successfully!", false);
        }
        catch (Exception ex)
        {
            ShowMessage(ex.Message, true);
        }
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _sessions.RemoveAll(s => s.Id == sessionId);
        _confirmRevokeId = null;
        ShowMessage("Session revoked.", false);
    }

    private void ShowMessage(string msg, bool isError)
    {
        _message = msg;
        _messageIsError = isError;
    }
}

