@namespace sv_bb4112eb02274c47a87b1948b8692560.Components.Pages.Settings
@using sv_bb4112eb02274c47a87b1948b8692560.Services
@inject ISettingsService SettingsService

<div class="card">
    <div class="card-header"><h5 class="mb-0">Appearance</h5></div>
    <div class="card-body">
        @if (_loading)
        {
            <div class="text-center p-4"><div class="spinner-border" role="status"></div></div>
        }
        else
        {
            @if (!string.IsNullOrEmpty(_message))
            {
                <div class="alert alert-success alert-dismissible fade show" role="alert">
                    @_message
                    <button type="button" class="btn-close" @onclick="() => _message = null"></button>
                </div>
            }

            <div class="row">
                <div class="col-md-7">
                    <!-- Theme -->
                    <div class="mb-4">
                        <h6>Theme</h6>
                        <div class="btn-group" role="group">
                            @foreach (var theme in new[] { "Light", "Dark", "System" })
                            {
                                <input type="radio" class="btn-check" name="theme" id="@($"theme-{theme}")"
                                       checked="@(_theme == theme)"
                                       @onchange="() => _theme = theme" />
                                <label class="btn btn-outline-primary" for="@($"theme-{theme}")">@theme</label>
                            }
                        </div>
                    </div>

                    <!-- Font Size -->
                    <div class="mb-4">
                        <h6>Font Size</h6>
                        <div class="btn-group" role="group">
                            @foreach (var size in new[] { "Small", "Medium", "Large" })
                            {
                                <input type="radio" class="btn-check" name="fontSize" id="@($"size-{size}")"
                                       checked="@(_fontSize == size)"
                                       @onchange="() => _fontSize = size" />
                                <label class="btn btn-outline-secondary" for="@($"size-{size}")">@size</label>
                            }
                        </div>
                    </div>

                    <!-- Language -->
                    <div class="mb-4">
                        <h6>Language</h6>
                        <select class="form-select" style="max-width:250px;" @bind="_language">
                            <option value="en">English</option>
                            <option value="es">Español</option>
                            <option value="fr">Français</option>
                            <option value="de">Deutsch</option>
                            <option value="ja">日本語</option>
                            <option value="zh">中文</option>
                        </select>
                    </div>

                    <!-- Compact Mode -->
                    <div class="mb-4 form-check form-switch">
                        <input type="checkbox" class="form-check-input" id="compactMode" @bind="_compactMode" />
                        <label class="form-check-label" for="compactMode">Compact Mode</label>
                    </div>

                    <button class="btn btn-primary" @onclick="SaveAsync">Save</button>
                </div>

                <!-- Live Preview -->
                <div class="col-md-5">
                    <h6>Preview</h6>
                    <div class="border rounded p-3 @GetPreviewClasses()" style="@GetPreviewStyles()">
                        <h6 style="@GetPreviewFontStyle()">Sample Heading</h6>
                        <p style="@GetPreviewFontStyle()" class="@(_compactMode ? "mb-1" : "mb-3")">
                            This is how your content will look with the selected settings.
                        </p>
                        <button class="btn btn-sm btn-primary">Sample Button</button>
                        <div class="mt-2">
                            <span class="badge bg-secondary">Tag</span>
                            <span class="badge bg-info ms-1">Label</span>
                        </div>
                    </div>
                </div>
            </div>
        }
    </div>
</div>

@code {
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;
    private bool _loading = true;
    private string? _message;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _message = "Appearance settings saved!";
    }

    private string GetPreviewClasses()
    {
        return _theme == "Dark" ? "bg-dark text-light" : "bg-light text-dark";
    }

    private string GetPreviewStyles()
    {
        var padding = _compactMode ? "padding: 0.5rem;" : "padding: 1rem;";
        return padding;
    }

    private string GetPreviewFontStyle()
    {
        var size = _fontSize switch
        {
            "Small" => "font-size: 0.85rem;",
            "Large" => "font-size: 1.25rem;",
            _ => "font-size: 1rem;"
        };
        return size;
    }
}

